import { Component, ElementRef, Input, SimpleChanges, ViewChild, OnChanges } from '@angular/core';
import { Category } from '@rsApp/modules/interfaces/category.interface';
import { CategoryService } from '../../provider/category.service';

@Component({
  selector: 'app-categories-swiper',
  templateUrl: 'categories-swiper.component.html',
  styleUrls: ['categories-swiper.component.scss'],
})
export class CategoriesSwiperComponent implements OnChanges {
  @Input() slidesPerView = 'auto';
  @Input() spaceBetween: string = '16';
  @Input() category: Category = null;
  @Input() disable: boolean = true;
  @ViewChild('swiper') swiperRef?: ElementRef<HTMLElement>;

  public localeCode;
  constructor(public categoryService: CategoryService) {}

  ngOnChanges(changes: SimpleChanges) {
    if (changes['category'] && this.category?.SubCategories?.length) {
      setTimeout(() => this.updateSwiper(), 0); // need to update margin of swiper with Cat doesn't have images
    }
  }

  private updateSwiper() {
    const swiperEl = this.swiperRef?.nativeElement as any;
    if (swiperEl?.swiper) {
      swiperEl.swiper.params.spaceBetween = this.spaceBetween;
      swiperEl.swiper.update();
    }
  }

  onErrorImage(event) {
    const img = event.srcElement.shadowRoot.children[0];
    img.src = 'assets/imgs/DefaultMissingImage.jpg';
  }

  navigateSpecificCategory(categoryCode, categoryName) {
    if (this.disable) return;
    this.categoryService.navigateToCategoryPage(categoryCode, categoryName);
  }
}
