import { Component, Input } from '@angular/core';
import { Router } from '@angular/router';
import { Department } from '@rsApp/modules/interfaces/category.interface';
import { CategoryService } from '../../provider/category.service';
@Component({
  selector: 'app-popular-departments',
  templateUrl: 'popular-departments.html',
  styleUrls: ['popular-departments.scss'],
})
export class PopularDepartmentsComponent {
  @Input() departments: Department[];
  @Input() departmentLoaded: boolean = false;
  magImg: string = `<mag-img src></mag-img>`;
  private LIMITATION = 9;
  public skeletonCategories = [...Array(this.LIMITATION).keys()];
  constructor(
    private router: Router,
    public categoryService: CategoryService
  ) {}

  viewAllCategories() {
    this.router.navigate(['/tabs/browse/all-categories']);
  }

  getNumberOfDepartments() {
    if (this.departments) return this.departments.length;
    return 0;
  }

  onErrorImage(event) {
    const img = event.srcElement.shadowRoot.children[0];
    img.src = 'assets/imgs/DefaultMissingImage.jpg';
  }
  navigateSpecificCategory(categoryCode: string, categoryName: string) {
    this.categoryService.navigateToCategoryPage(categoryCode, categoryName);
  }
}
