import { Location } from '@angular/common';
import { Component, NgZone, OnDestroy, OnInit } from '@angular/core';
import { ActivatedRoute, NavigationEnd, Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { NgxPubSubService } from '@pscoped/ngx-pub-sub';
import { ProductSearchService } from '@rsApp/modules/ecom-v2/product/providers/product-search.service';
import { Category } from '@rsApp/modules/interfaces/category.interface';
import { IMagCategoryParams } from '@rsApp/modules/interfaces/search.interface';
import { DxpComponentService } from '@rsApp/modules/utils/providers/dxp.component.service';
import { convertToArray, preprocessParams } from '@rsApp/modules/utils/providers/utils';
import cloneDeep from 'lodash/cloneDeep';
import { distinctUntilChanged, filter, Subject, Subscription, takeUntil } from 'rxjs';
import { CategoryService } from '../../provider/category.service';

@Component({
  selector: 'app-category',
  templateUrl: 'category.component.html',
  styleUrls: ['category.component.scss'],
})
export class CategoryPageComponent implements OnInit, OnDestroy {
  public MINIMUM_NUMBER_CATEGORY = 3;
  public category: Category = null;
  public title = '';
  public catCode: string;
  public loaded: boolean;
  public isAllCategoryMode: boolean = false;
  public isAddedListener: boolean = false;
  public destroy$ = new Subject<void>();
  public eventListenerFn: any;
  public catSub: Subscription = null;

  public isDepartment: string = '';
  public keyword: string = '';
  public queryParamsString: string;
  public disableCategory: boolean = true;
  public fromDetailPage: boolean = false;
  constructor(
    public router: Router,
    public route: ActivatedRoute,
    public categoryService: CategoryService,
    private productSearchService: ProductSearchService,
    public dxpComponentService: DxpComponentService,
    public events: NgxPubSubService,
    public translate: TranslateService,
    public ngZone: NgZone,
    private location: Location
  ) {
    this.router.events
      .pipe(
        takeUntil(this.destroy$),
        filter((e) => e instanceof NavigationEnd)
      )
      .subscribe(() => {
        this.fromDetailPage = history.state?.fromDetailPage ?? false;
        this.fromDetailPage && this.clearNavigationState();
      });
  }

  clearNavigationState() {
    const cleanState = { ...history.state };
    delete cleanState.fromDetailPage;

    history.replaceState(cleanState, document.title, location.pathname + location.search);
  }

  isLocalSearch() {
    return !!this.title;
  }

  async hasCategories() {
    return new Promise<boolean>((resolve) => {
      this.categoryService
        .getCategories()
        .pipe(takeUntil(this.destroy$), distinctUntilChanged())
        .subscribe((category) => {
          if (category && category.length > 0) {
            resolve(true);
          }
        });
    });
  }

  ngOnInit(): void {
    this.route.queryParams.pipe(takeUntil(this.destroy$)).subscribe(async (params) => {
      const { paramsFromUrls, cats } = this.getParamsFromUrls(params);
      await this.hasCategories();
      this.initCategoryData(paramsFromUrls);
      this.catCode = cats;
      this.loaded = true;
    });
    document.body.addEventListener('eventChangedParamsMagSearch', this.handleParamChange);
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
    document.body.removeEventListener('eventChangedParamsMagSearch', this.handleParamChange);
  }

  clearQueryParams() {
    const path = this.router.url.split('?')[0];
    this.location.replaceState(path);
  }

  ionViewDidLeave() {
    this.productSearchService.setKeyWord('');
    this.isAllCategoryMode = false;
  }

  getParamsFromUrls(params?: any) {
    const queryParams = params || this.route.snapshot.queryParams;
    const { cats, catsName, dept, brands, promo, diet, featured } = queryParams || {};
    const paramsFromUrls = {
      categoryCodes: cats?.split(';'),
      categoryNames: catsName?.split(';'),
      dept: convertToArray(dept),
      brands: convertToArray(brands),
      promo: convertToArray(promo),
      diet: convertToArray(diet),
      featured: convertToArray(featured),
    };
    return {
      paramsFromUrls,
      cats,
      catsName,
    };
  }

  async initCategory() {
    const { paramsFromUrls, cats, catsName } = this.getParamsFromUrls();
    await this.initCategoryData(paramsFromUrls);
    this.categoryService.saveCategoryCodesAndNames([cats], [catsName]);
    this.catCode = cats;
    this.loaded = true;
  }

  handleParamChange = async (event: CustomEvent) => {
    const dxpParams = preprocessParams(event?.detail);
    if (!dxpParams || this.productSearchService.isProductSearchListPage()) return;
    const { cats = [], catsName = [], featured = [] } = dxpParams || {};
    this.prepareInfo(cats, catsName, featured);
  };

  prepareInfo(categoryCodes: string[], categoryNames: string[], featured: string[]) {
    if (featured?.length > 0) {
      this.title = '';
    }
    if (this.category?.Code === categoryCodes.at(-1)) return; // No change in category, do nothing
    this.isAllCategoryMode = categoryCodes?.length === 0 && categoryNames?.length === 0 && featured?.length === 0;
    if (this.isAllCategoryMode) {
      this.title = this.translate.instant('browse.titleAllCategories');
      this.category = null;
      this.categoryService.navigateToAllCategories();
    } else {
      this.category = cloneDeep(this.categoryService.getCategoryByCode(categoryCodes));
      this.title = categoryNames.at(-1) || '';
    }
  }

  async initCategoryData({
    categoryCodes = [],
    categoryNames = [],
    brands = [],
    dept = [],
    promo = [],
    diet = [],
    featured = [],
  }: {
    categoryCodes: string[];
    categoryNames: string[];
    brands: string[];
    dept: string[];
    promo: string[];
    diet: string[];
    featured: string[];
  }) {
    this.catSub = this.categoryService.getCategories().subscribe(async (categories) => {
      if (!categories) return;
      this.prepareInfo(categoryCodes, categoryNames, featured);
      // Get keyword for search
      const keyword = (await this.productSearchService.getKeyWordString()) || '';
      // Prepare filters
      const filterParams: IMagCategoryParams = {
        Categories: categoryCodes,
        Brands: brands,
        Departments: dept,
        Promotions: promo,
        DietaryInterest: diet,
        Featured: featured || [],
      };

      this.setParamsChange(keyword, filterParams);
      this.catSub?.unsubscribe();
      this.catSub = null;
    });
  }

  setParamsChange(keyword: string, filterParams: any): void {
    this.disableCategory = true;
    this.ngZone.run(() => {
      this.isDepartment = '';
      this.keyword = keyword || '';
      if (typeof filterParams === 'object' && filterParams !== null) {
        if (this.fromDetailPage) {
          Object.assign(filterParams, { timeChange: new Date().getTime() });
          this.fromDetailPage = false;
        }
        this.queryParamsString = JSON.stringify(filterParams);
      }
    });
  }

  onContentLoaded() {
    this.disableCategory = false;
  }
}
