import { Component, OnDestroy, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { Category } from '@rsApp/modules/interfaces/category.interface';
import { CategoryService } from '../../provider/category.service';
import { Subject, takeUntil } from 'rxjs';

@Component({
  selector: 'app-all-categories',
  templateUrl: 'all-categories.component.html',
  styleUrls: ['all-categories.component.scss'],
})
export class AllCategoriesPageComponent implements OnInit, OnDestroy {
  private LIMITATION = 11;
  public skeletonCategories = [...Array(this.LIMITATION).keys()];
  public categories: Category[] = [];
  public destroy$ = new Subject<boolean>();

  constructor(
    public router: Router,
    public categoryService: CategoryService
  ) {}

  ngOnInit() {
    this.categoryService
      .getCategories()
      .pipe(takeUntil(this.destroy$))
      .subscribe((value) => {
        this.categories = value;
      });
  }

  ionViewWillEnter() {
    this.categoryService.loadCategories();
  }

  ngOnDestroy() {
    this.destroy$.next(true);
    this.destroy$.complete();
  }

  navigateSpecificCategory(categoryCode: string, categoryName: string) {
    this.categoryService.navigateToCategoryPage([categoryCode], [categoryName]);
  }
}
