import { NgModule } from '@angular/core';
import { CategoryPageComponent } from './pages/category/category.component';
import { BrowseModule } from './browse.module';
import { RouterModule, Routes } from '@angular/router';
import { BrowsePageComponent } from './browse.component';
import { AllCategoriesPageComponent } from './pages/all-categories/all-categories.component';
import { AppGuardsWithoutAuth } from '../utils/guard';

const routes: Routes = [
  {
    path: '',
    component: BrowsePageComponent,
  },
  {
    path: 'all-categories',
    component: AllCategoriesPageComponent,
  },
  {
    path: 'category',
    component: CategoryPageComponent,
  },
  {
    path: 'subcategory',
    component: CategoryPageComponent,
  },
  {
    path: 'product',
    loadChildren: () => import('../ecom-v2/product/product-routing.module').then((m) => m.ProductRoutingModule),
    canActivate: AppGuardsWithoutAuth,
    data: {
      hideTab: true,
    },
  },
];

@NgModule({
  imports: [RouterModule.forChild(routes), BrowseModule],
  exports: [RouterModule],
})
export class BrowsePageRoutingModule {}
