import { Component, OnInit, OnDestroy } from '@angular/core';
import { Router } from '@angular/router';
import { Department } from '../interfaces/category.interface';
import { CategoryService } from './provider/category.service';
import { catchError, Subject, takeUntil } from 'rxjs';

@Component({
  selector: 'browse-page',
  templateUrl: './browse.component.html',
  styleUrls: ['./browse.component.scss'],
})
export class BrowsePageComponent implements OnInit, OnDestroy {
  public departments: Department[];
  isSimpleHeader: boolean = true;
  isLocalSearch: boolean = false;
  isShowBackButton: boolean = false;
  public destroy$ = new Subject<boolean>();
  public departmentLoaded: boolean = false;
  constructor(
    private categoryService: CategoryService,
    public router: Router
  ) {}

  ngOnInit() {
    this.categoryService
      .getDepartments()
      .pipe(
        takeUntil(this.destroy$),
        catchError(() => {
          this.departmentLoaded = true;
          return [];
        })
      )
      .subscribe((value) => {
        if (value) {
          this.departments = value;
          this.departmentLoaded = true;
        }
      });
  }

  ngOnDestroy() {
    this.destroy$.next(true);
    this.destroy$.complete();
  }

  ionViewWillEnter() {
    this.categoryService.resetCategoryAndDepartment();
  }
}
